import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Personal Gateway and Multiple Entry Points","description":"Channel normalization, event deduplication, attention inbox, device registration, and mobile access for the Hearth Personal Gateway.","frontmatter":{"title":"Personal Gateway and Multiple Entry Points","description":"Channel normalization, event deduplication, attention inbox, device registration, and mobile access for the Hearth Personal Gateway.","outline":[2,3]},"headers":[],"relativePath":"en/architecture/gateway.md","filePath":"en/architecture/gateway.md","lastUpdated":null}'),l={name:"en/architecture/gateway.md"};function o(r,e,s,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<p class="eyebrow">PERSONAL GATEWAY</p><h1 id="personal-gateway-and-multiple-entry-points" tabindex="-1">Personal Gateway and Multiple Entry Points <a class="header-anchor" href="#personal-gateway-and-multiple-entry-points" aria-label="Permalink to &quot;Personal Gateway and Multiple Entry Points&quot;">​</a></h1><p class="lead">How users, email, calendars, IM, GitHub, web pages, files, and devices are normalized into deduplicable, traceable events.</p><h2 id="personal-gateway-and-multiple-entry-points-1" tabindex="-1">Personal Gateway and Multiple Entry Points <a class="header-anchor" href="#personal-gateway-and-multiple-entry-points-1" aria-label="Permalink to &quot;Personal Gateway and Multiple Entry Points&quot;">​</a></h2><p>Personal Gateway is the sole entry point between Hearth and the outside world. It is responsible for:</p><ul><li>identifying users, devices, and channels;</li><li>receiving text, voice, files, images, web pages, email, calendar, and scheduled events;</li><li>converting them uniformly into <code>Event</code>;</li><li>deduplicating, ordering, rate-limiting, and source tagging;</li><li>determining which events enter the attention inbox;</li><li>maintaining device registration, online status, and pairing relationships;</li><li>providing secure APIs and push notifications for mobile devices instead of exposing local ports.</li></ul><p>The Gateway does not perform long-running task reasoning or directly execute business actions.</p><h3 id="input-channels" tabindex="-1">Input Channels <a class="header-anchor" href="#input-channels" aria-label="Permalink to &quot;Input Channels&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Channel</th><th>Typical Input</th><th>Handling</th></tr></thead><tbody><tr><td>CLI</td><td>Commands, scripts, development debugging</td><td>Direct to Gateway; structured output supported</td></tr><tr><td>Web/PWA</td><td>Text, files, drag-and-drop, sharing</td><td>Task cards and approval center</td></tr><tr><td>Mobile</td><td>Text, voice, sharing, photo capture, notifications</td><td>Approve, view, take over, initiate</td></tr><tr><td>IM</td><td>Messages, files, forwarding</td><td>Normalized by Channel Adapter</td></tr><tr><td>Email</td><td>Email and attachments</td><td>Read-only sync, drafts, send pending approval</td></tr><tr><td>Calendar</td><td>Calendar events and invitations</td><td>Read-only, conflict checking, writes pending approval</td></tr><tr><td>Device</td><td>Files, screen, camera, sensors</td><td>Device capabilities and authorization</td></tr><tr><td>Cron/Watch</td><td>Timers, file changes, web page changes</td><td>Trigger evaluation</td></tr><tr><td>API/MCP</td><td>External service events</td><td>Normalized by Connector</td></tr></tbody></table><p>Stage 0 only designs the channel model and UI states; Stage 1 only connects Web and CLI; Stage 2 then connects the first real Connector. Do not roll out all channels from the start.</p><h3 id="event-normalization-and-deduplication" tabindex="-1">Event Normalization and Deduplication <a class="header-anchor" href="#event-normalization-and-deduplication" aria-label="Permalink to &quot;Event Normalization and Deduplication&quot;">​</a></h3><p>All channel events contain at least:</p><ul><li>source type and source id;</li><li>trust level;</li><li>user/device identity;</li><li>original timestamp;</li><li>content reference or redacted summary;</li><li>conversation/thread association;</li><li>idempotency key;</li><li>whether it is allowed to trigger proactive Tasks.</li></ul><p>Default policies:</p><ul><li>the same event from the same source is processed only once;</li><li>duplicate notifications are merged;</li><li>low-value events are only recorded, not reasoned over;</li><li>untrusted sources cannot create high-risk Mandates;</li><li>external content cannot override system Policy.</li></ul><h3 id="attention-inbox" tabindex="-1">Attention Inbox <a class="header-anchor" href="#attention-inbox" aria-label="Permalink to &quot;Attention Inbox&quot;">​</a></h3><p>The Attention Inbox is not a message list but the “minimal set that requires human handling”:</p><ul><li>actions that require approval;</li><li>Tasks that require additional information;</li><li>Tasks that failed and cannot recover automatically;</li><li>browsers or desktops that require takeover;</li><li>completed Artifacts;</li><li>summaries that can be reviewed later.</li></ul><p>By default, the following do not enter the inbox: low-confidence observations with no side effects, duplicate events filtered by rules, pure state changes, and failed retries that do not require human decisions.</p><p>Ordering criteria:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>priority = risk × blockedness × deadline × userImpact × reversibilityPenalty</span></span></code></pre></div><p>After the user closes a channel, no other channel can bypass it.</p><h3 id="device-registration-and-capability-catalog" tabindex="-1">Device Registration and Capability Catalog <a class="header-anchor" href="#device-registration-and-capability-catalog" aria-label="Permalink to &quot;Device Registration and Capability Catalog&quot;">​</a></h3><p>During device registration, the device reports:</p><ul><li>device id and public key;</li><li>operating system and version;</li><li>online status and heartbeat;</li><li>available capabilities: files, terminal, browser, screen, camera, microphone, notifications, clipboard;</li><li>accessible local data scope;</li><li>security boundaries and Sandbox support;</li><li>user-granted capabilities;</li><li>device lease and expiration time.</li></ul><p>Device capabilities are not permanent authorizations. After a Task ends, temporary capabilities should be reclaimed automatically.</p><h3 id="mobile-access" tabindex="-1">Mobile Access <a class="header-anchor" href="#mobile-access" aria-label="Permalink to &quot;Mobile Access&quot;">​</a></h3><p>Phones are Hearth&#39;s remote entry point, not the default execution authority. The first version of Stage 4 supports only:</p><ol><li>Viewing Tasks, status, and Artifacts;</li><li>Approving high-risk actions;</li><li>Taking over abnormal Tasks;</li><li>Initiating new Tasks;</li><li>Receiving high-signal notifications.</li></ol><p>Security requirements:</p><ul><li>Access through a secure tunnel or push service;</li><li>Do not expose Agent ports directly;</li><li>Device pairing uses short-lived codes and public keys;</li><li>Approvals bind to a nonce, action parameters, and expiration time;</li><li>Notifications contain only redacted summaries;</li><li>If a device is lost, all tokens and leases can be revoked.</li></ul>',31)])])}const g=t(l,[["render",o]]);export{u as __pageData,g as default};
